mapper.select:
select distinct start_time,end_time
from vm_channel_video_plan_his_t t1
where  t1.device_code = #{deviceCode}
and t1.channel_code= #{channelCode}
AND t1.tenant_id = #{customerCode}
and t1.data_time = #{dateTmp}
and t1.industry_code =  #{industryCode}

select t.channel_status from vm_channel_info_t t
where t.channel_code= #{channelCode}
      and t.device_code= #{deviceCode}
